import React, { useState } from "react";
import { BrowserRouter as Router, Routes, Route, Link, Navigate, useLocation } from "react-router-dom";
import Home from "./Home";
import Register from "./pages/Register";
import Login from "./pages/Login";
import BMICalculator from "./pages/BMICalculator";
import BMIHistory from "./pages/BMIHistory";
import Dashboard from "./pages/Dashboard";
import AdminDashboard from "./pages/AdminDashboard";
import Chatbot from "./components/Chatbot";
import Profile from "./pages/Profile";

function NavigationBar({ token, decoded, isMenuOpen, setIsMenuOpen, handleLogout }) {
  const location = useLocation();

  const linkClass = (path, activeClass, inactiveClass) =>
    location.pathname === path ? activeClass : inactiveClass;

  return (
    <nav className="glass sticky top-0 z-50 mx-4 mt-4 rounded-2xl shadow-lg">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-16">
          <Link to="/" className="flex items-center space-x-2 group">
            <img src="/logo192.png" alt="Public Health App" className="w-8 h-8 rounded-lg object-cover group-hover:scale-110 transition-transform duration-300" />
            <span className="text-xl font-bold bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent">
              Public Health App
            </span>
          </Link>

          <div className="hidden md:flex items-center space-x-2">
            {!token && (
              <Link to="/" className={linkClass("/", "px-4 py-2 rounded-xl bg-blue-50 text-blue-700 font-medium", "px-4 py-2 rounded-xl text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition-all duration-300 font-medium")}>
                Home
              </Link>
            )}

            {token && (
              <Link to="/bmi" className={linkClass("/bmi", "px-4 py-2 rounded-xl bg-blue-50 text-blue-700 font-medium", "px-4 py-2 rounded-xl text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition-all duration-300 font-medium")}>
                BMI
              </Link>
            )}

            {decoded?.role === "admin" && (
              <Link to="/admin" className={linkClass("/admin", "px-4 py-2 rounded-xl bg-purple-50 text-purple-700 font-medium", "px-4 py-2 rounded-xl text-purple-700 hover:bg-purple-50 hover:text-purple-600 transition-all duration-300 font-medium")}>
                Admin
              </Link>
            )}

            {token && (
              <Link to="/dashboard" className={linkClass("/dashboard", "px-4 py-2 rounded-xl bg-blue-50 text-blue-700 font-medium", "px-4 py-2 rounded-xl text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition-all duration-300 font-medium")}>
                Dashboard
              </Link>
            )}

            {token && (
              <Link to="/bmi-history" className={linkClass("/bmi-history", "px-4 py-2 rounded-xl bg-blue-50 text-blue-700 font-medium", "px-4 py-2 rounded-xl text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition-all duration-300 font-medium")}>
                History
              </Link>
            )}

            {token && (
              <Link
                to="/profile"
                title="Open profile"
                className={linkClass(
                  "/profile",
                  "inline-flex items-center gap-2 rounded-xl bg-gradient-to-r from-blue-500 to-purple-600 px-4 py-2 font-medium text-white shadow-md shadow-blue-500/20 transition-all duration-300 hover:scale-105",
                  "inline-flex items-center gap-2 rounded-xl border border-blue-100 bg-white px-4 py-2 font-medium text-gray-800 transition-all duration-300 hover:bg-blue-50 hover:text-blue-700"
                )}
              >
                <span className="flex h-6 w-6 items-center justify-center rounded-full bg-white/20 text-xs font-bold text-white">
                  {decoded?.role === "admin" ? "A" : "U"}
                </span>
                Profile
              </Link>
            )}

            {!token && (
              <Link to="/register" className={linkClass("/register", "px-4 py-2 rounded-xl bg-blue-50 text-blue-700 font-medium", "px-4 py-2 rounded-xl text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition-all duration-300 font-medium")}>
                Register
              </Link>
            )}

            {!token ? (
              <Link to="/login" className="btn-primary ml-2">
                Login
              </Link>
            ) : (
              <button onClick={handleLogout} className="ml-2 bg-gradient-to-r from-red-500 to-red-600 text-white px-4 py-2 rounded-xl font-medium hover:shadow-lg hover:shadow-red-500/30 hover:scale-105 active:scale-95 transition-all duration-300">
                Logout
              </button>
            )}
          </div>

          <button onClick={() => setIsMenuOpen(!isMenuOpen)} className="md:hidden p-2 rounded-xl hover:bg-gray-100 transition-colors">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              {isMenuOpen ? (
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              ) : (
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
              )}
            </svg>
          </button>
        </div>

        {isMenuOpen && (
          <div className="md:hidden pb-4 animate-slide-down">
            <div className="flex flex-col space-y-2">
              {!token && <Link to="/" className={linkClass("/", "px-4 py-2 rounded-xl bg-blue-50 text-blue-700", "px-4 py-2 rounded-xl text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition-colors")} onClick={() => setIsMenuOpen(false)}>Home</Link>}
              {token && <Link to="/bmi" className={linkClass("/bmi", "px-4 py-2 rounded-xl bg-blue-50 text-blue-700", "px-4 py-2 rounded-xl text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition-colors")} onClick={() => setIsMenuOpen(false)}>BMI</Link>}
              {decoded?.role === "admin" && <Link to="/admin" className={linkClass("/admin", "px-4 py-2 rounded-xl bg-purple-50 text-purple-700", "px-4 py-2 rounded-xl text-purple-700 hover:bg-purple-50 hover:text-purple-600 transition-colors")} onClick={() => setIsMenuOpen(false)}>Admin</Link>}
              {token && <Link to="/dashboard" className={linkClass("/dashboard", "px-4 py-2 rounded-xl bg-blue-50 text-blue-700", "px-4 py-2 rounded-xl text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition-colors")} onClick={() => setIsMenuOpen(false)}>Dashboard</Link>}
              {token && <Link to="/bmi-history" className={linkClass("/bmi-history", "px-4 py-2 rounded-xl bg-blue-50 text-blue-700", "px-4 py-2 rounded-xl text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition-colors")} onClick={() => setIsMenuOpen(false)}>History</Link>}
              {token && <Link to="/profile" className="px-4 py-2 rounded-xl bg-gradient-to-r from-blue-500 to-purple-600 text-white shadow-md shadow-blue-500/20 transition-all duration-300" onClick={() => setIsMenuOpen(false)}>Profile</Link>}
              {!token && <Link to="/register" className={linkClass("/register", "px-4 py-2 rounded-xl bg-blue-50 text-blue-700", "px-4 py-2 rounded-xl text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition-colors")} onClick={() => setIsMenuOpen(false)}>Register</Link>}
              {!token && <Link to="/login" className="px-4 py-2 rounded-xl text-blue-600 hover:bg-blue-50 transition-colors" onClick={() => setIsMenuOpen(false)}>Login</Link>}
              {token && <button onClick={handleLogout} className="px-4 py-2 rounded-xl text-red-600 hover:bg-red-50 transition-colors text-left">Logout</button>}
            </div>
          </div>
        )}
      </div>
    </nav>
  );
}

function App() {
  const token = localStorage.getItem("token");
  const decoded = token ? JSON.parse(atob(token.split(".")[1])) : null;
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const handleLogout = () => {
    localStorage.removeItem("token");
    window.location.reload();
  };

  return (
    <Router>
      <div className="min-h-screen">
        <NavigationBar
          token={token}
          decoded={decoded}
          isMenuOpen={isMenuOpen}
          setIsMenuOpen={setIsMenuOpen}
          handleLogout={handleLogout}
        />

        {/* Main Content with Animation */}
        <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 animate-fade-in">
          <Routes>
            <Route path="/" element={token ? <Navigate to="/dashboard" /> : <Home />} />
            <Route path="/bmi" element={token ? <BMICalculator /> : <Navigate to="/login" />} />
            <Route path="/register" element={<Register />} />
            <Route path="/login" element={<Login />} />
            <Route path="/dashboard" element={<Dashboard />} />
            <Route path="/admin" element={<AdminDashboard />} />
            <Route path="/bmi-history" element={token ? <BMIHistory /> : <Navigate to="/login" />} />
            <Route path="/profile" element={token ? <Profile /> : <Navigate to="/login" />} />
          </Routes>
        </main>

        {/* Chatbot - Shows on all pages after login */}
        {token && <Chatbot />}
      </div>
    </Router>
  );
}

export default App;

